Recipes, each compiled against the real compiler.

Add two tracks and set them up:

```frust
pub fn run() -> String = {
    let drums = station_track_add("Drums");
    let bass = station_track_add("Bass");
    station_track_set_volume_db(drums, -8.0);
    station_track_set_volume_db(bass, -6.0);
    station_track_set_pan(bass, 0.3);
    "Added Drums and Bass"
}
```

Report every track:

```frust
pub fn run() -> String = {
    let count = station_track_count();
    station_log_i64("tracks", count);
    for track in 1..(count + 1) {
        station_log(station_track_name(track));
        station_log_f64("volume dB", station_track_volume_db(track));
    };
    "done"
}
```

Set every track to -12 dB:

```frust
pub fn run() -> String = {
    let mut track = 1;
    while (track <= station_track_count()) {
        station_track_set_volume_db(track, -12.0);
        track = track + 1;
    };
    "All tracks set to -12 dB"
}
```

Rename and pan track 1:

```frust
pub fn run() -> String = {
    station_track_set_name(1, "Lead");
    station_track_set_pan(1, -0.5);
    "Track 1 is now Lead, panned left"
}
```

List the muted tracks:

```frust
pub fn run() -> String = {
    let count = station_track_count();
    if (count == 0) {
        return "The project has no tracks";
    };
    let mut track = 1;
    while (track <= count) {
        if (station_track_muted(track) == 1) {
            station_log(station_track_name(track));
        };
        track = track + 1;
    };
    "Listed the muted tracks above"
}
```
